class Solution {
public:
    vector<TreeNode*> result;
    unordered_set<int> toDel;

    TreeNode* dfs(TreeNode* node, bool parentDeleted) {
        if (!node) return nullptr;
        bool deleted = toDel.count(node->val) > 0;
        node->left = dfs(node->left, deleted);
        node->right = dfs(node->right, deleted);
        if (deleted) return nullptr;
        if (parentDeleted) result.push_back(node);
        return node;
    }

    vector<TreeNode*> delNodes(TreeNode* root, vector<int>& to_delete) {
        result.clear();
        toDel.clear();
        for (int v : to_delete) toDel.insert(v);
        dfs(root, true);
        return result;
    }
};
